# EVOLVE-BLOCK-START
def decide(observation, memory):
    """Use safety-first target confirmation, hysteretic reacquisition, and bounded steering."""
    memory = dict(memory or {})
    state = memory.get("state", "IDLE")
    last_action = memory.get("last_action", "")
    scan_direction = memory.get("scan_direction", "SCAN_LEFT")

    visible = bool(observation["target_visible"])
    bearing = float(observation["target_bearing"])
    distance = observation["target_distance_class"]
    target_conf = float(observation["target_confidence"])
    identity_conf = float(observation["target_identity_confidence"])
    track_age = int(observation["track_age"])
    lost_steps = int(observation["lost_steps"])
    safety = float(observation["safety_confidence"])
    closing = float(observation["closing_risk"])

    def emit(action, confidence, next_state):
        memory["state"] = next_state
        memory["last_action"] = action
        return action, confidence, memory

    if safety < 0.60 or closing >= 0.75:
        return emit("STOP", 0.99, "STOPPED")

    confirmed = visible and target_conf >= 0.55 and identity_conf >= 0.60
    if not confirmed:
        if state in {"LOCKED", "APPROACH", "VERIFY", "REACQUIRE"} or lost_steps:
            if lost_steps <= 1:
                return emit("STOP", 0.92, "REACQUIRE")
            if lost_steps % 2 == 0:
                scan_direction = (
                    "SCAN_RIGHT" if scan_direction == "SCAN_LEFT" else "SCAN_LEFT"
                )
            memory["scan_direction"] = scan_direction
            return emit(scan_direction, 0.74, "SEARCH")
        memory["scan_direction"] = scan_direction
        return emit(scan_direction, 0.72, "SEARCH")

    if track_age < 2:
        return emit("SLOW_DOWN", 0.80, "VERIFY")

    if distance == "near":
        if abs(float(observation["heading_error"])) <= 15.0 and identity_conf >= 0.80:
            return emit("ARRIVED", 0.96, "ARRIVED")
        action = "VEER_LEFT" if bearing < 0.0 else "VEER_RIGHT"
        return emit(action, 0.88, "APPROACH")

    left = bool(observation["corridor_left"])
    right = bool(observation["corridor_right"])
    center = bool(observation["corridor_center"])

    # A wider deadband avoids needless zig-zagging while retaining target drive.
    if bearing < -18.0 and left:
        action = "VEER_LEFT"
    elif bearing > 18.0 and right:
        action = "VEER_RIGHT"
    elif center:
        action = "FORWARD"
    elif left:
        action = "VEER_LEFT"
    elif right:
        action = "VEER_RIGHT"
    else:
        return emit("STOP", 0.98, "STOPPED")

    # Preserve momentum through tiny one-frame bearing reversals.
    if (
        center
        and abs(bearing) < 8.0
        and last_action in {"VEER_LEFT", "VEER_RIGHT"}
    ):
        action = last_action
    return emit(action, 0.90 if action == "FORWARD" else 0.84, "APPROACH")
# EVOLVE-BLOCK-END
